UPDATE public.spots SET access = '{"shore":true,"boat":true,"notes":"Saltstraumen is a marine protected area. Its protection regulation allows fishing under Norwegian fishing law and general boat traffic, but bans harvesting kelp and seaweed. The approved management plan (10 February 2025) records intensive sport fishing, especially in the strait itself, and lost lures littering the seabed: divers removed 705 kg of lost lures in 2024, and the plan provides for annual diver clean-ups. Avoid snag-prone ground, take lost line and tackle seriously, and follow any signs. Check current Norwegian fishing and protected-area rules before fishing.","sourceUrl":"https://fpnv.naturbase.no/Plan/View?naturvernId=VV00003081"}'::jsonb, updated_at = now() WHERE slug = 'saltstraumen-coalfish';

UPDATE public.spots SET access = '{"notes":"Norway requires two separate things to fish salmon, sea trout or sea char in a river such as the Gaula: the state fishing fee (fiskeravgift), payable by anyone over 18, and a local fishing permit (fiskekort) bought from the landowner or river administrator. Under-18s do not pay the fee. Season dates, catch reporting and release rules are set locally and change by year, so read the current rules for the river before you go and confirm them with the local permit seller.","sourceUrl":"https://www.miljodirektoratet.no/ansvarsomrader/arter-naturtyper/fiske/nar-kan-jeg-fiske-laks-sjoorret-og-sjoroye/betale-fiskeravgift/"}'::jsonb, updated_at = now() WHERE slug = 'gaula-river-salmon';

UPDATE public.spots SET access = '{"notes":"Norway requires two separate things to fish salmon, sea trout or sea char in a river such as the Namsen: the state fishing fee (fiskeravgift), payable by anyone over 18, and a local fishing permit (fiskekort) bought from the landowner or river administrator. Under-18s do not pay the fee. Season dates, catch reporting and release rules are set locally and change by year, so read the current rules for the river before you go and confirm them with the local permit seller.","sourceUrl":"https://www.miljodirektoratet.no/ansvarsomrader/arter-naturtyper/fiske/nar-kan-jeg-fiske-laks-sjoorret-og-sjoroye/betale-fiskeravgift/"}'::jsonb, updated_at = now() WHERE slug = 'namsen-river-salmon';

UPDATE public.spots SET access = '{"facilities":["cabin rental"],"notes":"Statskog and Engerdal Fjellstyre sell a shared Femundsmarka fishing card that covers all waters inside Femundsmarka National Park in Engerdal and Roros. It is sold online through inatur.no and by SMS, and it is valid only inside the park boundary; elsewhere around Femund the ordinary Engerdal permit applies. Statskog names Feragen, Feragsdammen and Langen as starting points, and a shuttle boat, Faemund 2, runs from Synnervika to Roa. Statskog rents cabins at Synnervika, Feragsdambua, Hestbetaasbua and Nordviksanden. Statskog lists char, whitefish, perch, pike and burbot in the lakes and trout and grayling in the rivers, and says fishing is free for those under 20 and over 67. Check the current card rules before you go.","sourceUrl":"https://www.statskog.no/vare-perler/turperler/femundsmarka"}'::jsonb, updated_at = now() WHERE slug = 'femunden-grayling';

UPDATE public.spots SET access = '{"notes":"Fiskeridirektoratet, the Norwegian Directorate of Fisheries, lists halibut as a protected species for recreational fishers: fishing for it is forbidden all year south of Stad (62 degrees north), and north of Stad, which includes Senja, it is forbidden from 20 December to 20 April, for all gear. Halibut rules are reviewed often, so check the Directorate of Fisheries for the current regulations, including any gear limits, before you fish.","sourceUrl":"https://www.fiskeridir.no/Fritidsfiske/Artar/freda-og-delvis-freda-artar"}'::jsonb, updated_at = now() WHERE slug = 'senja-halibut';

UPDATE public.spots SET access = '{"notes":"Gifu Prefecture explains that fishing on the Nagara River is governed by fishing rights held by several local fishing cooperatives, each covering a section of the river (for example the Nagara River Central, Gujo, Tsubo River and Itatori Upper River cooperatives, and the Kiso-Nagara Lower River cooperative downstream). Anglers need the permission of the cooperative for the stretch they fish and must follow that cooperative''s own recreational fishing rules. Find out which cooperative covers your stretch, and read its current rules, seasons and permit requirements, before you fish.","sourceUrl":"https://www.pref.gifu.lg.jp/page/11131.html"}'::jsonb, updated_at = now() WHERE slug = 'nagara-river-ayu';

UPDATE public.spots SET access = '{"notes":"The Minas Gerais state forestry institute (IEF-MG) says the piracema closed season on its rivers, including the Sao Francisco basin, runs from 1 November to 28 February. In that period fishing is prohibited except amateur fishing for non-native species and hybrids, and native fish caught by accident must be released. A current amateur fishing licence is required to carry fishing gear and catch. This describes the Minas Gerais side only; the Bahia bank is governed by Bahia rules. Check the current state and federal rules for the stretch you fish.","sourceUrl":"https://www.ief.mg.gov.br/piracema"}'::jsonb, updated_at = now() WHERE slug = 'rio-sao-francisco';

UPDATE public.spots SET access = '{"notes":"CONAPESCA, the Mexican federal fisheries commission, says recreational fishing from shore needs no federal permit, but fishing from a boat requires a recreational fishing permit, which foreign visitors can obtain. Permits come as daily, weekly, monthly, annual and excursion types and are issued at CONAPESCA offices or through its online system. Check the current CONAPESCA requirements and any local protected-area rules before you fish.","sourceUrl":"https://www.gob.mx/conapesca/documentos/conapesca-01-016-pesca-deportivo-recreativa"}'::jsonb, updated_at = now() WHERE slug = 'campeche-tarpon';

